import{DERBY_CONFIG as v}from"./config.min.js";export function trackAt(t,l=v){const r=l.track,o=r.slopeSine,e=r.slopeLength,n=r.transitionLength,a=o*(e+n/2);if(t<=e)return{sin:o,cos:Math.sqrt(1-o*o),curvature:0,height:a-o*t};if(t<e+n){const d=t-e,h=o*(1-d/n),s=Math.sqrt(1-h*h);return{sin:h,cos:s,curvature:o/n/s,height:a-o*e-o*(d-d*d/(2*n))}}return{sin:0,cos:1,curvature:0,height:0}}export function startHeight(t=v){return trackAt(0,t).height}export function sideRubOf(t,l=v){const r=l.physics.wobble;if(t.balance<0)return t.sideRub+r.extra+r.wheelie;if(t.balance>=r.safe)return t.sideRub;const o=(r.safe-t.balance)/r.safe;return t.sideRub+r.extra*o*o}export function runCar(t,l=null,{record:r=0}={},o=v){const e=o.physics,n=e.g,a=e.dt,d=o.track.courseLength,h=t.mass,s=h+t.rotatingMass,i=l===null?0:o.laneDefects[l]||0,c=t.axleMu*t.axleRatio,f=sideRubOf(t,o),u=.5*e.airDensity*t.cdA,k=o.track.slopeLength,D=c+e.rollingResistance+i,F=(L,g)=>{const M=L-t.comX,b=trackAt(M,o),A=h*(n*b.cos+g*g*b.curvature),y=M>k?f:t.sideRub;return(h*n*b.sin-D*A-y-u*g*g)/s},x=r>0?[{t:0,s:0,v:0}]:null,N=r>0?Math.round(r/a):0;let p=0,m=0,w=0,R=0;const T=Math.round(e.maxSeconds/a);for(;R<T;){const L=F(p,m),g=m+L*a/2,M=F(p+m*a/2,g),b=p+g*a,A=m+M*a;if(R++,b>=d){const y=(d-p)/(b-p),S=w+a*y,_=m+(A-m)*y;return x&&x.push({t:S,s:d,v:_}),{time:S,speed:_,dnf:!1,samples:x}}if(A<=0&&R>1)return{time:e.maxSeconds,speed:0,dnf:!0,samples:x,stoppedAt:p};p=b,m=A,w=R*a,x&&R%N===0&&x.push({t:w,s:p,v:m})}return{time:e.maxSeconds,speed:m,dnf:!0,samples:x,stoppedAt:p}}export function shownTime(t){return Math.round(t*1e3)/1e3}export function runRace(t,l=v){const r=l.track.lanes,o=t.map(s=>{const i=[];for(let c=0;c<r;c++)i.push(runCar(s,c,{},l));return i}),e=[];for(let s=0;s<r;s++)e.push(t.map((i,c)=>{const f=(c+s)%r,u=o[c][f];return{car:c,lane:f,time:shownTime(u.time),dnf:u.dnf}}));const n=t.map((s,i)=>{let c=0;for(const f of e)c+=f[i].time;return shownTime(c/e.length)}),a=t.map((s,i)=>{let c=e[0][i];for(const f of e)f[i].time<c.time&&(c=f[i]);return c}),d=t.map((s,i)=>i).sort((s,i)=>n[s]-n[i]||s-i),h=[];for(let s=0;s<r;s++){let i=0,c=0;for(const f of e)for(const u of f)u.lane===s&&(i+=u.time,c++);h.push(c?shownTime(i/c):null)}return{heats:e,average:n,best:a,standings:d,laneAverage:h}}export function neutralTime(t,l=v){return runCar(t,null,{},l).time}export function explain(t,{blockCdA:l,bestCdA:r,idealBalance:o},e=v){const n=neutralTime(t,e),a=e.rules[t.rules]||e.rules.standard,d=e.physics.axleFriction.stock,h=d*e.physics.axleFriction.deburred*e.physics.axleFriction.polish.reduce((u,k)=>u*k,1)*e.physics.axleFriction.graphite,s=u=>neutralTime({...t,...u},e),i=u=>({balance:u,comX:t.rearAxle-u}),c=t.mass-t.ballast,f=[{id:"weight",saved:s({mass:c})-n,more:n-s({mass:a.maxMass})},{id:"balance",saved:s(i((t.rearAxle-t.frontAxle)/2))-n,more:n-s(i(o))},{id:"axles",saved:s({axleMu:d})-n,more:n-s({axleMu:h})},{id:"alignment",saved:s({sideRub:e.physics.sideRub.misaligned})-n,more:n-s({sideRub:e.physics.sideRub.aligned})},{id:"shape",saved:s({cdA:l})-n,more:n-s({cdA:r})}];return{time:n,lines:f}}
